1	// Offline route resolution: match a request against configured route prefixes
2	// and join the remainder onto the upstream base path without any network I/O.
3	package contractsentinel
4	
5	import (
6		"bytes"
7		"encoding/json"
8		"fmt"
9		"net/netip"
10		"net/url"
11		"sort"
12		"strings"
13	)
14	
15	// Route is one configured route: an id, accepted methods, a path prefix and
16	// the upstream URL requests on that route are forwarded to. An optional
17	// queryTransforms list rewrites the request query string after the route has
18	// been selected.
19	type Route struct {
20		ID              string            `json:"id"`
21		Methods         []string          `json:"methods"`
22		PathPrefix      string            `json:"pathPrefix"`
23		Upstream        string            `json:"upstream"`
24		QueryTransforms []*QueryTransform `json:"-"`
25	
26		// queryTransformsRaw holds the undecoded queryTransforms value until
27		// Config.UnmarshalJSON validates it once the route's position in its own
28		// config is known.
29		queryTransformsRaw json.RawMessage
30	}
31	
32	// QueryTransform is one rule in a route's queryTransforms array: op is
33	// "set", "remove" or "rename"; name is matched against decoded parameter
34	// names, value (set only) is used literally, and to (rename only) is the
35	// literal replacement name.
36	type QueryTransform struct {
37		Op    string `json:"op"`
38		Name  string `json:"name"`
39		Value string `json:"value"`
40		To    string `json:"to"`
41	}
42	
43	// routeJSON mirrors Route but keeps every field raw: the basic fields are
44	// type-checked in Config.UnmarshalJSON with the route's position (and, when
45	// available, its id), so a wrong field type is reported on that route rather
46	// than as a generic JSON decode error, and queryTransforms can surface
47	// null, wrong types and malformed rules the same way.
48	type routeJSON struct {
49		ID              json.RawMessage `json:"id"`
50		Methods         json.RawMessage `json:"methods"`
51		PathPrefix      json.RawMessage `json:"pathPrefix"`
52		Upstream        json.RawMessage `json:"upstream"`
53		QueryTransforms json.RawMessage `json:"queryTransforms"`
54	}
55	
56	// decodeRoute type-checks and decodes one raw route object. loc is the
57	// route's 1-based location in its config (e.g. "route 2"). The element's JSON
58	// type is checked first: a null entry or any non-object value fails on the
59	// entry itself, naming the position, the required object type and the type
60	// actually received, instead of falling through to a missing-field error such
61	// as a missing id. Field type errors then carry that location and, when the
62	// route supplies a valid non-empty string id anywhere in its object (even
63	// after the offending field), that id. Missing fields stay silent here and
64	// are rejected later by validate, which preserves the existing missing-field
65	// behavior.
66	func decodeRoute(data []byte, loc string) (Route, *Failure) {
67		elem := bytes.TrimSpace(data)
68		if len(elem) == 0 || elem[0] != '{' {
69			return Route{}, failuref("invalid_config",
70				"%s: route entry must be an object, got %s", loc, jsonTypeName(elem))
71		}
72		var rj routeJSON
73		if err := json.Unmarshal(elem, &rj); err != nil {
74			// The element already parsed as one JSON value and starts with '{';
75			// an object that cannot be read is a syntax failure rather than a
76			// field type error.
77			return Route{}, failuref("invalid_config", "config is not valid JSON: %v", err)
78		}
79	
80		var route Route
81		// Type-check id first so it can identify the route on an error in any
82		// later field regardless of object order. Only a valid non-empty JSON
83		// string becomes the label; a wrong-typed id is reported against the id
84		// field and never rendered (e.g. as a number or object) as the route's
85		// identity.
86		if f := decodeStringField(rj.ID, loc, "id", &route.ID); f != nil {
87			return Route{}, f
88		}
89		label := loc
90		if route.ID != "" {
91			label = routeLabel(loc, route.ID)
92		}
93	
94		if f := decodeMethodsField(rj.Methods, label, &route.Methods); f != nil {
95			return Route{}, f
96		}
97		if f := decodeStringField(rj.PathPrefix, label, "pathPrefix", &route.PathPrefix); f != nil {
98			return Route{}, f
99		}
100		if f := decodeStringField(rj.Upstream, label, "upstream", &route.Upstream); f != nil {
101			return Route{}, f
102		}
103		route.queryTransformsRaw = rj.QueryTransforms
104		return route, nil
105	}
106	
107	// decodeStringField type-checks a raw route field that must hold a string.
108	// An absent field is left as the zero value for later required-field
109	// validation; null or any non-string JSON value fails here.
110	func decodeStringField(raw json.RawMessage, label, field string, dst *string) *Failure {
111		if len(raw) == 0 {
112			return nil
113		}
114		if !jsonString(raw, dst) {
115			return failuref("invalid_config", "%s: %s must be a string", label, field)
116		}
117		return nil
118	}
119	
120	// decodeMethodsField type-checks methods: it must be an array of strings
121	// when present. An absent field is left nil for later required-field
122	// validation; null or any non-array value fails the field, and a number,
123	// boolean, object or null entry fails with the offending entry's position.
124	func decodeMethodsField(raw json.RawMessage, label string, dst *[]string) *Failure {
125		if len(raw) == 0 {
126			return nil
127		}
128		body := bytes.TrimSpace(raw)
129		if string(body) == "null" || len(body) == 0 || body[0] != '[' {
130			return failuref("invalid_config", "%s: methods must be an array of strings", label)
131		}
132		var elems []json.RawMessage
133		if err := json.Unmarshal(body, &elems); err != nil {
134			return failuref("invalid_config", "%s: methods must be an array of strings", label)
135		}
136		methods := make([]string, 0, len(elems))
137		for i, elem := range elems {
138			var m string
139			if !jsonString(bytes.TrimSpace(elem), &m) {
140				return failuref("invalid_config", "%s: methods entry %d must be a string", label, i+1)
141			}
142			methods = append(methods, m)
143		}
144		*dst = methods
145		return nil
146	}
147	
148	// parseQueryTransforms decodes and validates the raw queryTransforms array
149	// of one route. loc identifies the route; rule errors additionally carry a
150	// 1-based rule index.
151	func parseQueryTransforms(raw json.RawMessage, loc, id string) ([]*QueryTransform, *Failure) {
152		body := strings.TrimSpace(string(raw))
153		if body == "null" {
154			return nil, failuref("invalid_config", "%s: queryTransforms must not be null", routeLabel(loc, id))
155		}
156		var elems []json.RawMessage
157		if err := json.Unmarshal([]byte(body), &elems); err != nil {
158			return nil, failuref("invalid_config", "%s: queryTransforms must be an array", routeLabel(loc, id))
159		}
160		transforms := make([]*QueryTransform, 0, len(elems))
161		for i, elem := range elems {
162			ruleLoc := fmt.Sprintf("%s, queryTransforms rule %d", routeLabel(loc, id), i+1)
163			if string(bytes.TrimSpace(elem)) == "null" {
164				return nil, failuref("invalid_config", "%s: rule must not be null", ruleLoc)
165			}
166			var fields map[string]json.RawMessage
167			if err := json.Unmarshal(elem, &fields); err != nil {
168				return nil, failuref("invalid_config", "%s: rule must be a JSON object", ruleLoc)
169			}
170	
171			qt := &QueryTransform{}
172			opRaw, ok := fields["op"]
173			switch {
174			case !ok:
175				return nil, failuref("invalid_config", "%s: op is required", ruleLoc)
176			case !jsonString(opRaw, &qt.Op):
177				return nil, failuref("invalid_config", "%s: op must be a string", ruleLoc)
178			case qt.Op != "set" && qt.Op != "remove" && qt.Op != "rename":
179				return nil, failuref("invalid_config", "%s: unknown op %q (only set, remove and rename are supported)", ruleLoc, qt.Op)
180			}
181	
182			nameRaw, ok := fields["name"]
183			switch {
184			case !ok:
185				return nil, failuref("invalid_config", "%s: name is required", ruleLoc)
186			case !jsonString(nameRaw, &qt.Name):
187				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
188			case qt.Name == "":
189				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
190			}
191	
192			valueRaw, hasValue := fields["value"]
193			toRaw, hasTo := fields["to"]
194			switch qt.Op {
195			case "set":
196				if !hasValue {
197					return nil, failuref("invalid_config", "%s: set requires a string value", ruleLoc)
198				}
199				if !jsonString(valueRaw, &qt.Value) {
200					return nil, failuref("invalid_config", "%s: value must be a string", ruleLoc)
201				}
202			case "remove":
203				if hasValue {
204					return nil, failuref("invalid_config", "%s: remove must not include a value", ruleLoc)
205				}
206			case "rename":
207				if hasValue {
208					return nil, failuref("invalid_config", "%s: rename must not include a value", ruleLoc)
209				}
210				switch {
211				case !hasTo:
212					return nil, failuref("invalid_config", "%s: rename requires a non-empty string to", ruleLoc)
213				case !jsonString(toRaw, &qt.To):
214					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
215				case qt.To == "":
216					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
217				}
218			}
219			transforms = append(transforms, qt)
220		}
221		return transforms, nil
222	}
223	
224	// jsonString decodes raw into s and reports whether raw is a JSON string
225	// (null, numbers, objects and arrays fail).
226	func jsonString(raw json.RawMessage, s *string) bool {
227		if len(raw) == 0 || raw[0] != '"' {
228			return false
229		}
230		return json.Unmarshal(raw, s) == nil
231	}
232	
233	// routeLabel renders the human-readable route location, adding the id when
234	// the configuration supplied one.
235	func routeLabel(loc, id string) string {
236		if id != "" {
237			return fmt.Sprintf("%s (id %q)", loc, id)
238		}
239		return loc
240	}
241	
242	// Config is the resolve configuration: a flat array of routes.
243	type Config struct {
244		Routes []Route `json:"routes"`
245	}
246	
247	// UnmarshalJSON first confirms the document is one syntactically valid JSON
248	// value, then checks its structure: the top-level value must be a JSON object
249	// and, when present, the routes field must hold an array. A syntactically
250	// legal value of the wrong shape (an array, string, number, boolean or null
251	// at the top level; a non-array routes, null included) is an invalid_config
252	// naming both the required type and the type received, never a JSON parse
253	// failure. The routes array is then decoded one entry at a time, each entry
254	// type-checked and validated against its 1-based position in this config; a
255	// non-object entry (null included) fails on that entry before any field is
256	// inspected. Decoding entries from raw values means wrong field types are
257	// reported on the offending route (with its id when available) instead of
258	// as a generic JSON syntax failure. The position comes from the array
259	// decoded here, so configs parsed concurrently or interleaved in the same
260	// process cannot shift each other's route numbering. A broken JSON document
261	// still fails the outer decode and is reported as a parse failure, without a
262	// guessed route position or field.
263	func (cfg *Config) UnmarshalJSON(data []byte) error {
264		// First confirm the document is one syntactically valid JSON value: only
265		// then is a wrong shape a structural error rather than a parse failure.
266		// This mirrors ParseRequest: broken syntax (including an empty file and a
267		// corrupt first route) stays a parse error with no guessed position.
268		var doc json.RawMessage
269		if err := json.Unmarshal(data, &doc); err != nil {
270			return err
271		}
272		body := bytes.TrimSpace(doc)
273		if body[0] != '{' {
274			return failuref("invalid_config", "config must be a JSON object, got %s", jsonTypeName(body))
275		}
276		var fields map[string]json.RawMessage
277		if err := json.Unmarshal(body, &fields); err != nil {
278			return err
279		}
280	
281		var rawRoutes []json.RawMessage
282		if raw, ok := fields["routes"]; ok {
283			body := bytes.TrimSpace(raw)
284			if len(body) == 0 || body[0] != '[' {
285				// null is a type error here, never an absent field: a config
286				// that explicitly supplies routes must supply an array.
287				return failuref("invalid_config", "routes must be an array, got %s", jsonTypeName(body))
288			}
289			if err := json.Unmarshal(body, &rawRoutes); err != nil {
290				return err
291			}
292		}
293	
294		// Pass 1: decode and type-check every entry, so a wrong field type on a
295		// later route fails before any queryTransforms validation (matching the
296		// precedence of decoding before validation).
297		cfg.Routes = make([]Route, len(rawRoutes))
298		for i, entry := range rawRoutes {
299			route, f := decodeRoute(entry, fmt.Sprintf("route %d", i+1))
300			if f != nil {
301				return f
302			}
303			cfg.Routes[i] = route
304		}
305		// Pass 2: validate each route's queryTransforms now that every position
306		// is known.
307		for i := range cfg.Routes {
308			route := &cfg.Routes[i]
309			if len(route.queryTransformsRaw) == 0 {
310				continue // field absent
311			}
312			loc := fmt.Sprintf("route %d", i+1)
313			transforms, f := parseQueryTransforms(route.queryTransformsRaw, loc, route.ID)
314			if f != nil {
315				return f
316			}
317			route.QueryTransforms = transforms
318			route.queryTransformsRaw = nil
319		}
320		return nil
321	}
322	
323	// Request is one resolution request: an HTTP method and a request target
324	// (path with an optional raw query string).
325	type Request struct {
326		Method string `json:"method"`
327		Target string `json:"target"`
328	}
329	
330	// Resolution is the successful result of matching a request.
331	type Resolution struct {
332		RouteID     string `json:"routeId"`
333		UpstreamURL string `json:"upstreamURL"`
334	}
335	
336	// Failure carries a stable machine-readable code and a human-readable reason.
337	type Failure struct {
338		Code       string   `json:"code"`
339		Reason     string   `json:"reason"`
340		Candidates []string `json:"candidates,omitempty"`
341	}
342	
343	func (f *Failure) Error() string { return f.Code + ": " + f.Reason }
344	
345	func failuref(code, format string, args ...any) *Failure {
346		return &Failure{Code: code, Reason: fmt.Sprintf(format, args...)}
347	}
348	
349	// ParseConfig parses and fully validates the route configuration.
350	func ParseConfig(data []byte) (*Config, *Failure) {
351		var cfg Config
352		if err := json.Unmarshal(data, &cfg); err != nil {
353			if f, ok := err.(*Failure); ok {
354				return nil, f
355			}
356			return nil, failuref("invalid_config", "config is not valid JSON: %v", err)
357		}
358		if f := cfg.validate(); f != nil {
359			return nil, f
360		}
361		return &cfg, nil
362	}
363	
364	func (cfg *Config) validate() *Failure {
365		seenIDs := make(map[string]int, len(cfg.Routes))
366		for i := range cfg.Routes {
367			route := &cfg.Routes[i]
368			loc := fmt.Sprintf("route %d", i+1)
369			if route.ID == "" {
370				return failuref("invalid_config", "%s: id must be non-empty", loc)
371			}
372			if first, ok := seenIDs[route.ID]; ok {
373				return failuref("invalid_config", "%s: duplicate id %q (already used by route %d)", loc, route.ID, first)
374			}
375			seenIDs[route.ID] = i + 1
376	
377			if len(route.Methods) == 0 {
378				return failuref("invalid_config", "%s (id %q): methods must be a non-empty array", loc, route.ID)
379			}
380			for _, method := range route.Methods {
381				switch {
382				case method == "":
383					return failuref("invalid_config", "%s (id %q): methods must not contain empty entries", loc, route.ID)
384				case method == "*":
385					// Wildcard matching any legal method.
386				case !isToken(method):
387					return failuref("invalid_config", "%s (id %q): invalid method %q", loc, route.ID, method)
388				}
389			}
390	
391			if f := validatePrefix(route.PathPrefix, loc, route.ID); f != nil {
392				return f
393			}
394			if f := validateUpstream(route.Upstream, loc, route.ID); f != nil {
395				return f
396			}
397		}
398		return nil
399	}
400	
401	func validatePrefix(prefix, loc, id string) *Failure {
402		switch {
403		case prefix == "" || prefix[0] != '/':
404			return failuref("invalid_config", "%s (id %q): pathPrefix must start with /", loc, id)
405		case prefix != "/" && strings.HasSuffix(prefix, "/"):
406			return failuref("invalid_config", "%s (id %q): pathPrefix must not end with / except for root", loc, id)
407		case strings.ContainsAny(prefix, "?#"):
408			return failuref("invalid_config", "%s (id %q): pathPrefix must not contain a query string or fragment", loc, id)
409		case !validPercentEscapes(prefix):
410			return failuref("invalid_config", "%s (id %q): pathPrefix contains an invalid percent escape", loc, id)
411		}
412		return nil
413	}
414	
415	func validateUpstream(raw, loc, id string) *Failure {
416		if strings.ContainsAny(raw, "?#") {
417			return failuref("invalid_config", "%s (id %q): upstream must not contain a query string or fragment", loc, id)
418		}
419		// Validate any bracketed host against the raw string before url.Parse:
420		// square brackets are the IP-literal marker, so whatever they enclose
421		// must be a legal IPv6 address (zone included) rather than a name or an
422		// IPv4 address. Doing this explicitly keeps the rule independent of
423		// url.Parse's parser strictness and lets the reason name the field and
424		// the actual problem instead of surfacing a generic URL parse error.
425		if f := validateBracketedUpstreamHost(raw, loc, id); f != nil {
426			return f
427		}
428		u, err := url.Parse(raw)
429		if err != nil {
430			return failuref("invalid_config", "%s (id %q): upstream is not a valid URL: %v", loc, id, err)
431		}
432		if u.Scheme != "http" && u.Scheme != "https" {
433			return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
434		}
435		if u.Host == "" {
436			return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
437		}
438		return nil
439	}
440	
441	// validateBracketedUpstreamHost checks the raw upstream's authority for an
442	// IP literal in square brackets: brackets are reserved for an IPv6 (or
443	// future IP-version) literal, so their content must parse as an IPv6 address
444	// — full form, compressed form or an IPv6 address with an embedded IPv4
445	// tail. A port, userinfo and a percent-encoded zone ("%25eth0") are allowed
446	// and never alter the literal's bytes; an empty pair of brackets, a plain
447	// hostname such as "[not-an-ip]", a bare IPv4 address such as
448	// "[127.0.0.1]" and a malformed IPv6 literal are rejected with a reason
449	// that names the route, its id and the upstream field. This is a content
450	// error in a syntactically valid JSON document, never a JSON parse failure.
451	func validateBracketedUpstreamHost(raw, loc, id string) *Failure {
452		// The authority starts after the scheme separator and ends at the first
453		// path slash (query and fragment were rejected by the caller).
454		schemeEnd := strings.Index(raw, "://")
455		if schemeEnd < 0 {
456			return nil // no scheme: the generic absolute-URL check reports this
457		}
458		authority := raw[schemeEnd+3:]
459		if i := strings.IndexByte(authority, '/'); i >= 0 {
460			authority = authority[:i]
461		}
462		// Any userinfo precedes the host and ends at the last '@'.
463		hostPort := authority
464		if i := strings.LastIndexByte(authority, '@'); i >= 0 {
465			hostPort = authority[i+1:]
466		}
467	
468		if !strings.ContainsAny(hostPort, "[]") {
469			return nil // ordinary reg-name (domain) or bare IPv4 host stays as-is
470		}
471		label := routeLabel(loc, id)
472		if !strings.HasPrefix(hostPort, "[") {
473			return failuref("invalid_config",
474				"%s: upstream bracketed host must be a valid IPv6 address: '[' may only enclose the host", label)
475		}
476		closeBracket := strings.IndexByte(hostPort, ']')
477		if closeBracket < 0 {
478			return failuref("invalid_config",
479				"%s: upstream bracketed host must be a valid IPv6 address but the closing ']' is missing", label)
480		}
481		literal := hostPort[1:closeBracket]
482		// The zone delimiter is percent-encoded in the URL ("%25"); decode the
483		// literal's escapes once so netip sees "fe80::1%eth0" while every other
484		// byte keeps its original spelling.
485		decoded, err := url.PathUnescape(literal)
486		if err != nil {
487			return invalidBracketedHost(label, literal)
488		}
489		addr, err := netip.ParseAddr(decoded)
490		if err != nil || !addr.Is6() {
491			// ParseAddr accepts a bare IPv4 address; brackets may only carry
492			// IPv6, so "[127.0.0.1]" is rejected even though it is a valid IP.
493			return invalidBracketedHost(label, literal)
494		}
495		return nil
496	}
497	
498	// invalidBracketedHost builds the content error for a bracketed host whose
499	// content is not a legal IPv6 literal.
500	func invalidBracketedHost(label, literal string) *Failure {
501		return failuref("invalid_config",
502			"%s: upstream host in brackets must be a valid IPv6 address, but %q is not a legal IPv6 address", label, literal)
503	}
504	
505	// requestJSON mirrors Request but keeps method and target raw, so a valid
506	// JSON document whose fields merely have the wrong JSON type is reported on
507	// the offending field instead of as a generic JSON decode error.
508	type requestJSON struct {
509		Method json.RawMessage `json:"method"`
510		Target json.RawMessage `json:"target"`
511	}
512	
513	// ParseRequest parses and validates one JSON request. Three failure shapes are
514	// kept apart: a document whose JSON syntax is broken fails as a parse failure
515	// without guessing a field; a syntactically valid non-object document (array,
516	// number, string, boolean or null) must be a JSON object; a valid object whose
517	// method or target is not a string fails on that field, naming the JSON type
518	// actually received (null counts as a type error, never as a missing field).
519	// method is always checked before target, regardless of the key order in the
520	// object. Only after both fields are present strings are their contents
521	// (required method, legal token, absolute target without a fragment or a bad
522	// percent escape) validated, so an empty string stays a content error.
523	func ParseRequest(data []byte) (*Request, *Failure) {
524		var doc json.RawMessage
525		if err := json.Unmarshal(data, &doc); err != nil {
526			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
527		}
528		body := bytes.TrimSpace(doc)
529		if len(body) == 0 || body[0] != '{' {
530			return nil, failuref("invalid_request", "request must be a JSON object")
531		}
532	
533		var rj requestJSON
534		if err := json.Unmarshal(body, &rj); err != nil {
535			// The document already parsed as one JSON value and starts with '{';
536			// keep this as a parse failure rather than a field error if the object
537			// itself cannot be read.
538			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
539		}
540	
541		var req Request
542		if f := decodeRequestStringField(rj.Method, "method", &req.Method); f != nil {
543			return nil, f
544		}
545		if f := decodeRequestStringField(rj.Target, "target", &req.Target); f != nil {
546			return nil, f
547		}
548	
549		switch {
550		case req.Method == "":
551			return nil, failuref("invalid_request", "method is required")
552		case !isToken(req.Method):
553			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
554		}
555		switch {
556		case req.Target == "" || req.Target[0] != '/':
557			return nil, failuref("invalid_request", "target must start with /")
558		case strings.Contains(req.Target, "#"):
559			return nil, failuref("invalid_request", "target must not contain a fragment")
560		case !validPercentEscapes(req.Target):
561			return nil, failuref("invalid_request", "target contains an invalid percent escape")
562		}
563		return &req, nil
564	}
565	
566	// decodeRequestStringField type-checks one request field that must hold a
567	// string. An absent field (no such key) is left as the zero value so the
568	// later content checks keep their "field is required" behavior; null or any
569	// non-string JSON value is a type error that names the field and the JSON
570	// type that was actually supplied.
571	func decodeRequestStringField(raw json.RawMessage, field string, dst *string) *Failure {
572		if len(raw) == 0 {
573			return nil
574		}
575		if jsonString(raw, dst) {
576			return nil
577		}
578		return failuref("invalid_request", "%s must be a string, got %s", field, jsonTypeName(raw))
579	}
580	
581	// jsonTypeName names the JSON type of a syntactically valid raw value, in the
582	// terms the request error reasons use: "null", "a boolean", "a number",
583	// "a string", "an array" or "an object".
584	func jsonTypeName(raw json.RawMessage) string {
585		switch bytes.TrimSpace(raw)[0] {
586		case 'n':
587			return "null"
588		case 't', 'f':
589			return "a boolean"
590		case '"':
591			return "a string"
592		case '[':
593			return "an array"
594		case '{':
595			return "an object"
596		default:
597			return "a number"
598		}
599	}
600	
601	// Resolve matches a validated request against a validated configuration and
602	// computes the upstream URL. Failure codes are route_not_found and
603	// route_conflict.
604	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
605		path := req.Target
606		if i := strings.IndexByte(path, '?'); i >= 0 {
607			path = path[:i]
608		}
609	
610		type candidate struct {
611			route    *Route
612			concrete bool
613		}
614		var matched []candidate
615		for i := range cfg.Routes {
616			route := &cfg.Routes[i]
617			concrete, wildcard := methodMatch(route.Methods, req.Method)
618			if !concrete && !wildcard {
619				continue
620			}
621			if !prefixMatch(route.PathPrefix, path) {
622				continue
623			}
624			matched = append(matched, candidate{route, concrete})
625		}
626		if len(matched) == 0 {
627			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
628		}
629	
630		// Longest prefix wins.
631		bestLen := 0
632		for _, c := range matched {
633			if n := len(c.route.PathPrefix); n > bestLen {
634				bestLen = n
635			}
636		}
637		winners := matched[:0]
638		for _, c := range matched {
639			if len(c.route.PathPrefix) == bestLen {
640				winners = append(winners, c)
641			}
642		}
643	
644		// Among equal prefixes a concrete method beats the wildcard.
645		var concrete []candidate
646		for _, c := range winners {
647			if c.concrete {
648				concrete = append(concrete, c)
649			}
650		}
651		if len(concrete) > 0 {
652			winners = concrete
653		}
654		if len(winners) > 1 {
655			ids := make([]string, 0, len(winners))
656			for _, c := range winners {
657				ids = append(ids, c.route.ID)
658			}
659			sort.Strings(ids)
660			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
661			f.Candidates = ids
662			return nil, f
663		}
664	
665		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
666		if f != nil {
667			return nil, f
668		}
669		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
670	}
671	
672	// methodMatch reports whether the method list matches the request method
673	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
674	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
675		for _, m := range methods {
676			switch {
677			case m == "*":
678				wildcard = true
679			case m == method:
680				concrete = true
681			}
682		}
683		return concrete, wildcard
684	}
685	
686	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
687	// treated as a separator and the root prefix matches every origin-path.
688	func prefixMatch(prefix, path string) bool {
689		if prefix == "/" {
690			return true
691		}
692		if path == prefix {
693			return true
694		}
695		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
696	}
697	
698	// joinUpstream strips the route prefix from the request path and joins the
699	// remainder onto the upstream base path with exactly one slash at the
700	// junction. The junction is one run of literal slashes: every trailing
701	// slash on the base path and every leading slash on the remainder are
702	// merged into that single slash, even when either side contributes
703	// several. Nothing else is normalized: slashes inside either part, the
704	// remainder's trailing slashes (once non-slash content has appeared),
705	// ".", ".." and percent escapes such as "%2F" are carried over byte for
706	// byte, never decoded first. The base path is sliced out of the raw
707	// upstream so joining never re-encodes, reorders or drops anything
708	// outside the junction. The raw query is preserved verbatim unless the
709	// route defines queryTransforms, in which case they rewrite it after
710	// route selection.
711	func joinUpstream(route *Route, path, target string) (string, *Failure) {
712		if _, err := url.Parse(route.Upstream); err != nil {
713			// Config validation already rejected this.
714			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
715		}
716	
717		var remainder string
718		switch {
719		case route.PathPrefix == "/":
720			// Root keeps the whole following path; "/" itself has an empty remainder.
721			if path != "/" {
722				remainder = path
723			}
724		default:
725			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
726		}
727	
728		// Slice the validated upstream raw so nothing outside the junction is
729		// normalized or re-escaped (scheme://[userinfo@]host[/base-path]).
730		schemeEnd := strings.Index(route.Upstream, "://")
731		tail := route.Upstream[schemeEnd+3:]
732		hostPart, basePath := tail, ""
733		if i := strings.IndexByte(tail, '/'); i >= 0 {
734			hostPart, basePath = tail[:i], tail[i:]
735		}
736	
737		// Collapse only the junction run: all trailing slashes of the base
738		// path meet all leading slashes of the remainder, and the junction
739		// keeps exactly one slash whether or not anything follows them. A
740		// remainder made entirely of slashes has no content past the run, so
741		// it likewise ends in that single slash.
742		baseTrimmed := strings.TrimRight(basePath, "/")
743		rest := strings.TrimLeft(remainder, "/")
744		joined := baseTrimmed + "/" + rest
745	
746		result := route.Upstream[:schemeEnd+3] + hostPart + joined
747		query, f := applyQueryTransforms(route.QueryTransforms, target)
748		if f != nil {
749			return "", f
750		}
751		return result + query, nil
752	}
753	
754	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
755	func isToken(s string) bool {
756		if s == "" {
757			return false
758		}
759		for i := 0; i < len(s); i++ {
760			if !isTokenChar(s[i]) {
761				return false
762			}
763		}
764		return true
765	}
766	
767	func isTokenChar(c byte) bool {
768		switch {
769		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
770			return true
771		}
772		switch c {
773		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
774			return true
775		}
776		return false
777	}
778	
779	// validPercentEscapes checks that every "%' is followed by two hex digits.
780	// Matching and joining stay on raw strings, but malformed escapes are rejected
781	// up front for both prefixes and request targets.
782	func validPercentEscapes(s string) bool {
783		for i := 0; i < len(s); i++ {
784			if s[i] != '%' {
785				continue
786			}
787			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
788				return false
789			}
790			i += 2
791		}
792		return true
793	}
794	
795	func isHex(c byte) bool {
796		switch {
797		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
798			return true
799		}
800		return false
801	}
802

