63		if f != nil {
64			fail(*f)
65		}
66		req, f := contractsentinel.ParseRequest(requestData)
67		if f != nil {
68			fail(*f)
69		}
70		resolution, f := contractsentinel.Resolve(cfg, req)
71		if f != nil {
72			fail(*f)
73		}
74	
75		// HTML escaping is disabled so a raw query such as "a=1&b=2" is emitted
76		// byte for byte instead of "&".
77		enc := json.NewEncoder(os.Stdout)
