84	// fail prints the error as JSON to stderr and exits non-zero; stdout is left
85	// untouched so no partial result is observable on failure.
86	func fail(f contractsentinel.Failure) {
87		enc := json.NewEncoder(os.Stderr)
88		enc.SetEscapeHTML(false)
89		_ = enc.Encode(f)
90		os.Exit(1)
91	}
