526	func TestResolveConflict(t *testing.T) {
527		cfg := mustConfig(t, `{
528		  "routes": [
529		    {"id": "zeta",  "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://z.internal"},
530		    {"id": "alpha", "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://a.internal"},
531		    {"id": "mid",   "methods": ["GET"], "pathPrefix": "/things", "upstream": "http://m.internal"}
532		  ]
533		}`)
534		req, f := ParseRequest([]byte(`{"method":"GET","target":"/things"}`))
535		if f != nil {
536			t.Fatalf("unexpected request failure: %+v", f)
537		}
538		_, rf := Resolve(cfg, req)
539		if rf == nil {
540			t.Fatal("expected route_conflict")
541		}
542		if rf.Code != "route_conflict" {
543			t.Fatalf("code = %q, want route_conflict", rf.Code)
544		}
545		want := []string{"alpha", "mid", "zeta"}
546		if len(rf.Candidates) != len(want) {
547			t.Fatalf("candidates = %v, want %v", rf.Candidates, want)
548		}
549		for i := range want {
550			if rf.Candidates[i] != want[i] {
551				t.Fatalf("candidates = %v, want sorted %v", rf.Candidates, want)
552			}
553		}
554	
555		// Concrete vs wildcard at same prefix is NOT a conflict.
556		cfg2 := mustConfig(t, `{
557		  "routes": [
558		    {"id": "b-wild", "methods": ["*"],  "pathPrefix": "/things", "upstream": "http://w.internal"},
559		    {"id": "a-get",  "methods": ["GET"],"pathPrefix": "/things", "upstream": "http://g.internal"}
560		  ]
561		}`)
562		res := resolveJSON(t, cfg2, `{"method":"GET","target":"/things/x"}`)
563		if res.RouteID != "a-get" {
564			t.Fatalf("routeId = %q, want a-get", res.RouteID)
565		}
566	
567		// Two wildcards with no concrete entry remain a conflict.
568		cfg3 := mustConfig(t, `{
569		  "routes": [
570		    {"id": "w1", "methods": ["*"], "pathPrefix": "/things", "upstream": "http://w1.internal"},
571		    {"id": "w2", "methods": ["*"], "pathPrefix": "/things", "upstream": "http://w2.internal"}
572		  ]
573		}`)
574		_, rf = Resolve(cfg3, mustReq(t, "POST", "/things/x"))
575		if rf == nil || rf.Code != "route_conflict" {
576			t.Fatalf("got %+v, want route_conflict between wildcard routes", rf)
577		}
578	}
