580	// configFromRoutes builds a config document from raw route objects, so the
581	// same routes can be parsed in different orders.
582	func configFromRoutes(routes ...string) string {
583		return `{"routes":[` + strings.Join(routes, ",") + `]}`
584	}
585	
586	func reversed(routes []string) []string {
587		out := make([]string, len(routes))
588		for i, r := range routes {
589			out[len(routes)-1-i] = r
590		}
591		return out
592	}
