594	func TestResolveLongestPrefixBeatsShorterConcreteMethods(t *testing.T) {
595		// Selection order: longest prefix first, concrete-vs-wildcard only among
596		// the longest-prefix winners. A concrete GET on a shorter prefix must
597		// never override a wildcard on a longer prefix, and several GET routes
598		// tied on the shorter prefix must not conflict once the longer prefix
599		// wins.
600		routes := []string{
601			`{"id":"short-one","methods":["GET"],"pathPrefix":"/a","upstream":"http://one.internal/s1"}`,
602			`{"id":"short-two","methods":["GET"],"pathPrefix":"/a","upstream":"http://two.internal/s2"}`,
603			`{"id":"long-wild","methods":["*"],"pathPrefix":"/a/b","upstream":"http://wild.internal/base"}`,
604		}
605	
606		cases := []struct {
607			name     string
608			request  string
609			upstream string
610		}{
611			{
612				name:     "longer wildcard beats shorter concrete GETs",
613				request:  `{"method":"GET","target":"/a/b/c/items"}`,
614				upstream: "http://wild.internal/base/c/items",
615			},
616			{
617				name:     "query string survives route selection verbatim",
618				request:  `{"method":"GET","target":"/a/b/c?keep=1&keep=2&empty=&x=%2f"}`,
619				upstream: "http://wild.internal/base/c?keep=1&keep=2&empty=&x=%2f",
620			},
621			{
622				name:     "target equal to the longer prefix keeps one junction slash",
623				request:  `{"method":"GET","target":"/a/b"}`,
624				upstream: "http://wild.internal/base/",
625			},
626			{
627				name:     "wildcard on the longer prefix also serves other methods",
628				request:  `{"method":"POST","target":"/a/b/c"}`,
629				upstream: "http://wild.internal/base/c",
630			},
631		}
632		for _, order := range [][]string{routes, reversed(routes)} {
633			cfg := mustConfig(t, configFromRoutes(order...))
634			for _, tc := range cases {
635				t.Run(tc.name, func(t *testing.T) {
636					res := resolveJSON(t, cfg, tc.request)
637					if res.RouteID != "long-wild" {
638						t.Errorf("routeId = %q, want long-wild", res.RouteID)
639					}
640					if res.UpstreamURL != tc.upstream {
641						t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
642					}
643				})
644			}
645		}
646	
647		// The shorter-prefix GET routes really are tied with each other: a
648		// request that only reaches their prefix does conflict, proving the
649		// longer prefix (not an absence of rivalry) is what decided the cases
650		// above.
651		cfg := mustConfig(t, configFromRoutes(routes...))
652		_, rf := Resolve(cfg, mustReq(t, "GET", "/a/c"))
653		if rf == nil || rf.Code != "route_conflict" {
654			t.Fatalf("got %+v, want route_conflict between the shorter-prefix GET routes", rf)
655		}
656		if want := []string{"short-one", "short-two"}; !equalStrings(rf.Candidates, want) {
657			t.Fatalf("candidates = %v, want %v", rf.Candidates, want)
658		}
659	}
