727	func TestResolveConflictOnlyAmongFinalCandidates(t *testing.T) {
728		// A conflict is reported only when the final candidates cannot be
729		// narrowed to one: shorter-prefix routes and same-prefix wildcard routes
730		// are already eliminated and must not appear in the candidate list, and
731		// no route may be returned as a success.
732		routes := []string{
733			`{"id":"z-short","methods":["GET"],"pathPrefix":"/a","upstream":"http://short.internal"}`,
734			`{"id":"wild-long","methods":["*"],"pathPrefix":"/a/b","upstream":"http://wild.internal"}`,
735			`{"id":"zeta","methods":["GET"],"pathPrefix":"/a/b","upstream":"http://z.internal"}`,
736			`{"id":"alpha","methods":["GET"],"pathPrefix":"/a/b","upstream":"http://a.internal"}`,
737		}
738		for _, order := range [][]string{routes, reversed(routes)} {
739			cfg := mustConfig(t, configFromRoutes(order...))
740	
741			res, rf := Resolve(cfg, mustReq(t, "GET", "/a/b/x"))
742			if res != nil {
743				t.Fatalf("got success %+v, want route_conflict", res)
744			}
745			if rf == nil || rf.Code != "route_conflict" {
746				t.Fatalf("got %+v, want route_conflict", rf)
747			}
748			if want := []string{"alpha", "zeta"}; !equalStrings(rf.Candidates, want) {
749				t.Fatalf("candidates = %v, want %v (lexicographic, no shorter-prefix or wildcard routes)", rf.Candidates, want)
750			}
751	
752			// The wildcard route at the conflicted prefix still serves methods
753			// that have no concrete rival there.
754			res = resolveJSON(t, cfg, `{"method":"POST","target":"/a/b/x"}`)
755			if res.RouteID != "wild-long" {
756				t.Fatalf("POST: routeId = %q, want wild-long", res.RouteID)
757			}
758	
759			// The shorter-prefix route still serves requests that never reach
760			// the conflicted prefix.
761			res = resolveJSON(t, cfg, `{"method":"GET","target":"/a/other"}`)
762			if res.RouteID != "z-short" {
763				t.Fatalf("GET /a/other: routeId = %q, want z-short", res.RouteID)
764			}
765		}
766	}
